transform.program:
# resolve_team.star -- find the monitored team's display metadata among the
# (relay-paginated, already-fully-walked) list_teams results.
# Predeclared params: teams (list of {id, key, name, description}), team_id (string).
# Output via `result`: {found: bool, team: {id, key, name} | None}.
#
# Never errors on a miss: an unresolvable team_id degrades to found=False / team=None
# rather than aborting the run, since cycles/issues below are fetched directly by
# team_id and do not depend on this step succeeding.

def _resolve(teams, team_id):
    for t in teams:
        if t.get("id") == team_id:
            return {
                "found": True,
                "team": {
                    "id": t.get("id"),
                    "key": t.get("key"),
                    "name": t.get("name"),
                },
            }
    return {"found": False, "team": None}

result = _resolve(teams, team_id)

# verdict.star -- merge team metadata into the final shape and compute
# delta_vs_previous per cycle against previous_run_output (this primitive's own
# prior output), never trusting or requiring it to be present.
#
# Predeclared params:
#   team                 {id, key, name} | None
#   team_found           bool
#   cycles               list of cycle_health.star records (no delta_vs_previous yet)
#   as_of                ISO 8601 timestamp string
#   previous_run_output  this primitive's own prior output object, or None on a first run
#
# Output via `result`: {team, as_of, cycles, summary} -- the full output contract.

def _prev_cycle_by_id(previous_run_output, cid):
    if previous_run_output == None:
        return None
    prev_cycles = previous_run_output.get("cycles")
    if prev_cycles == None:
        return None
    for pc in prev_cycles:
        if pc.get("id") == cid:
            return pc
    return None

def _delta_field(cur_metrics, prev_metrics, field):
    cv = cur_metrics.get(field)
    pv = prev_metrics.get(field)
    if cv == None or pv == None:
        return None
    return cv - pv

def _delta(cur_metrics, prev_cycle):
    if prev_cycle == None:
        return None
    prev_metrics = prev_cycle.get("metrics")
    if prev_metrics == None:
        return None
    return {
        "scope_creep_pct": _delta_field(cur_metrics, prev_metrics, "scope_creep_pct"),
        "carryover_pct": _delta_field(cur_metrics, prev_metrics, "carryover_pct"),
        "stale_issue_count": _delta_field(cur_metrics, prev_metrics, "stale_issue_count"),
        "completed_pct": _delta_field(cur_metrics, prev_metrics, "completed_pct"),
    }

def _with_deltas(cycles, previous_run_output):
    out = []
    for c in cycles:
        prev_cycle = _prev_cycle_by_id(previous_run_output, c.get("id"))
        merged = dict(c)
        merged["delta_vs_previous"] = _delta(c.get("metrics"), prev_cycle)
        out.append(merged)
    return out

def _summary(cycles, team_found, previous_run_output):
    at_risk_count = 0
    for c in cycles:
        if c.get("at_risk"):
            at_risk_count += 1
    return {
        "team_found": team_found,
        "cycles_analyzed": len(cycles),
        "at_risk_cycle_count": at_risk_count,
        "is_first_run": previous_run_output == None,
    }

_cycles_out = _with_deltas(cycles, previous_run_output)

result = {
    "team": team,
    "as_of": as_of,
    "cycles": _cycles_out,
    "summary": _summary(_cycles_out, team_found, previous_run_output),
}
